-- ============================================================================
-- 00439 — Demo profiles: negative signals + silver/gold peer badges (Scott
-- 2026-10-05, follow-up of 00438). Until now every demo « ses partenaires
-- disent » row was positive and bronze. Same rules as the live product:
--   · Marie L. #2  → « Ponctuel » OR   (vouchedTier: ≥30 counted votes)
--   · Thomas B. #3 → « Préparé » ARGENT (≥10)
--   · Hugo P. #8   → « Mal préparé » + « Imprudent » (amber ≥5 ACTIVE votes;
--     get_active_negative_count decays 1/month of gap, so the votes sit on
--     his last four outings), and 3 « surestimé » (level_over) on trail —
--     consistent with the persona (« premier ultra en préparation »,
--     declared avancé) and his poor reliability.
-- Voters are present co-participants of the outing; created_at = outing end
-- + 5h, counted_at = end + 26h (same as 00438).
-- ============================================================================
INSERT INTO reputation_votes (voter_id, voted_id, activity_id, badge_key, counted_at, created_at)
SELECT v.voter, v.voted, v.activity, v.badge, a.starts_at + a.duration + INTERVAL '26 hours', a.starts_at + a.duration + INTERVAL '5 hours'
